class ProductFootprint(BaseModel):
    """
    `ProductFootprint` is a data type which represents the carbon footprint
    of a product under a specific scope ([[#dt-carbonfootprint-scope]])
    and with values calculated in accordance with the [=PACT Methodology=].

    The objective of a `ProductFootprint` is to provide interoperability between
    the creator (the [=data owner=]) and the consumer (the [=data recipient=]) of
    ProductFootprints. The details on the exchange of ProductFootprints are
    specified in [[#api]].

    Conceptually, the data type <{ProductFootprint}> is modeled as a multi-purpose
    container for product-specific emissions factors which is supported by
    extensibility through [=Data Model Extensions=].

    Data Model Extensions enable [=data owners=] to exchange additional information
    related to a product with [=data recipients=]. The details are specified
    in [[#datamodelextension]] as well as [[!EXTENSIONS-GUIDANCE]], and [[!DATA-MODEL-EXTENSIONS]].

    Each `ProductFootprint` can and should be updated over time, for instance to
    incorporate new or refined data from [=data owners=] (see [[#lifecycle]]).

    """

    id: Annotated[
        UUID,
        Field(
            description='A unique identifier that a system uses to refer to the entire dataset of the PCF. \nThis is typically an automatically-generated number by the technology  solution to maintain \nthe required technical references to data within the system.\nUUID v4 [RFC4122](https://tools.ietf.org/html/rfc4122).\n',
            examples=['f4b1225a-bd44-4c8e-861d-079e4e1dfd69'],
        ),
    ]
    specVersion: Annotated[
        str,
        Field(
            description='The version of the PACT Tech Specs that the data being shared complies with. \nThis is a string in the format of "major.minor.patch" (e.g. "3.0.0").\n',
            examples=['3.0.0'],
            pattern='^\\d+\\.\\d+\\.\\d+(-\\d{8})?$',
        ),
    ]
    precedingPfIds: Annotated[
        Optional[list[UUID]],
        Field(
            description='A given PCF may change over time, due to updates to the calculation. \nThis field lists all id\'s that reflect "past versions" of the current PCF. \nThis is typically an automatically generated field of unique identifiers, \nmaintained by the technology solution.\n',
            examples=[
                [
                    'f4b1225a-bd44-4c8e-861d-079e4e1dfd69',
                    '079e425a-464f-528d-341d-4a944a1dfd70',
                ]
            ],
            min_length=1,
        ),
    ] = None
    version: Annotated[
        int,
        Field(
            description='The version number of the PCF; if changes are made to the PCF, \nthis version number will increment.\n',
            examples=[1, 3303],
            ge=0,
        ),
    ]
    created: Annotated[
        AwareDatetime,
        Field(
            description='The date and time when the PCF was created. This is typically an automatically \ngenerated field by the software solution.\n',
            examples=['2024-10-31T00:00:00Z'],
        ),
    ]
    updated: Annotated[
        Optional[AwareDatetime],
        Field(
            description='The date and time when the PCF was last updated. This is typically an automatically \ngenerated field by the software solution. If the data has never been updated, \ndo not include this property.\n'
        ),
    ] = None
    status: Annotated[
        Status,
        Field(
            description='The status of the PCF. `Active` means that the PCF is the most recent version \nand is the one that can be used CAN be used by a data recipients, e.g. for product \nfootprint calculations. `Deprecated` means that the PCF is no longer \nthe most recent version and SHOULD NOT be used by data recipients.\n\nSee [[#lifecycle]] for details.\n',
            examples=['Active'],
        ),
    ]
    statusComment: Annotated[
        Optional[str],
        Field(
            description='TODO: Move this description to #lifecycle\n\nIf defined, a descriptive reasoning explaining the current status of \nthe PCF, what was changed since the last version, etc. If the PCF was \nchanged since a previous version, indicate all methodological and/or \nproduction process change(s) that occurred to result in the PCF change. \nFor example, include the relevant change(s) from the list below:\n\nMethodological:\n- Access to new Emission Factor data (database, supplier-specific, company-specific)\n- Updated upstream data (i.e. upstream supplier updated their PCF based on methodology change)\n\nProduction Process:\n- Change in process\n- Change in feedstock\n- Change from conventional to certified sustainable material\n- Change in energy source\n- Change in upstream supplier\n- Updated upstream data (i.e. upstream supplier updated their PCF based on process change)\n\nSee [[#lifecycle]] for details.\n'
        ),
    ] = None
    validityPeriodStart: Annotated[
        Optional[AwareDatetime],
        Field(
            description='TODO: Create a separate paragraph on validity period and reference period\n\nThe <dfn>validity period</dfn> is the time interval during which the \nProductFootprint is declared as valid for use by a receiving [=data recipient=].\n\nThe validity period is OPTIONAL defined by the properties \n<{ProductFootprint/validityPeriodStart}> (including) and \n<{ProductFootprint/validityPeriodEnd}> (excluding).\n\nIf no validity period is specified, the ProductFootprint is valid for \n3 years starting with <{CarbonFootprint/referencePeriodEnd}>.\n\nIf a validity period is to be specified, then\n  1. the value of <{ProductFootprint/validityPeriodStart}> MUST be defined with value \n     greater than or equal to the value of <{CarbonFootprint/referencePeriodEnd}>.\n  2. the value of <{ProductFootprint/validityPeriodEnd}> MUST be defined with value\n\n     1. strictly greater than <{ProductFootprint/validityPeriodStart}>, and\n     2. less than or equal to <{CarbonFootprint/referencePeriodEnd}> + 3 years.\n'
        ),
    ] = None
    validityPeriodEnd: Annotated[
        Optional[AwareDatetime],
        Field(
            description='The end date and time of the validity period. See validityPeriodStart for more details.\n'
        ),
    ] = None
    companyName: Annotated[
        str,
        Field(
            description='The name of the company that is the ProductFootprint Data Owner\n',
            min_length=1,
        ),
    ]
    companyIds: Annotated[
        list[Urn],
        Field(
            description='The non-empty set of Uniform Resource Names ([[!RFC8141|URN]]). Each value of \nthis set is supposed to uniquely identify the ProductFootprint Data Owner. \nTODO: See Company Identifier section for details\n',
            examples=[
                ['urn:company:example:company1'],
                ['urn:company:example:company1', 'urn:company:example:company2'],
            ],
            min_length=1,
        ),
    ]
    productDescription: Annotated[
        str,
        Field(
            description='The free-form description of the product, including any additional relevant information \nsuch as production technology, packaging, process, feedstock and technical parameters \n(e.g. dimensions). Products which are services (i.e. consulting) should include a short\ndescription of the service.\n'
        ),
    ]
    productIds: Annotated[
        list[Urn],
        Field(
            description='The non-empty set of [=ProductIds=] in [=URN=] format. Each of the values in the set is \nsupposed to uniquely identify the product. See {#product-identifiers} for syntax and \nexamples.\n',
            min_length=1,
        ),
    ]
    productCategoryCpc: Annotated[
        str,
        Field(
            description='Advisement: DEPRECATED in 3.0. Superseded by <{ProductFootprint/productClassifications}>.\n\nThe UN Central Product Classification (CPC) that the given product belongs to.\n',
            min_length=1,
        ),
    ]
    productNameCompany: Annotated[
        str,
        Field(description='The non-empty trade name of the product.\n', min_length=1),
    ]
    comment: Annotated[
        str,
        Field(
            description='Advisement: OPTIONAL in 3.0.\n\nAdditional information related to the product footprint.\n\nWhereas the property <{ProductFootprint/productDescription}> contains product-level information, <{ProductFootprint/comment}> SHOULD be used for information and instructions related to the calculation of the footprint, or other information which informs the ability to interpret, to audit or to verify the Product Footprint.\n'
        ),
    ]
    pcf: Annotated[
        CarbonFootprint,
        Field(
            description='The carbon footprint of the given product with value conforming to the data \ntype <{CarbonFootprint}>.\n'
        ),
    ]
    extensions: Annotated[
        Optional[list[DataModelExtension]],
        Field(
            description='If defined, 1 or more data model extensions associated with the ProductFootprint.\nSee <{DataModelExtension}> for details.\n'
        ),
    ] = None


